INSERT INTO `ec_products` (`id`, `name`, `description`, `content`, `status`, `images`, `sku`, `order`, `quantity`, `allow_checkout_when_out_of_stock`, `with_storehouse_management`, `is_featured`, `brand_id`, `is_variation`, `sale_type`, `price`, `sale_price`, `start_date`, `end_date`, `length`, `wide`, `height`, `weight`, `tax_id`, `views`, `created_at`, `updated_at`, `stock_status`, `created_by_id`, `created_by_type`, `image`, `product_type`, `barcode`, `cost_per_item`) VALUES
(1, 'Smart Home Speaker (Digital)', '<p>Short Hooded Coat features a straight body, large pockets with button flaps, ventilation air holes, and a string detail along the hemline.</p>', '<p>Short Hooded Coat features a straight body, large pockets with button flaps, ventilation air holes, and a string detail along the hemline. The style is completed with a drawstring hood, featuring Rains’ signature built-in cap. Made from waterproof, matte PU, this lightweight unisex rain jacket is an ode to nostalgia through its classic silhouette and utilitarian design details.</p><p>- Casual unisex fit</p><p>- 64% polyester, 36% polyurethane</p><p>- Water column pressure: 4000 mm</p><p>- Model is 187cm tall and wearing a size S / M</p><p>- Unisex fit</p><p>- Drawstring hood with built-in cap</p><p>- Front placket with snap buttons</p><p>- Ventilation under armpit</p><p>- Adjustable cuffs</p><p>- Double welted front pockets</p><p>- Adjustable elastic string at hempen</p><p>- Ultrasonically welded seams</p><p>This is a unisex item, please check our clothing &amp; footwear sizing guide for specific Rains jacket sizing information. RAINS comes from the rainy nation of Denmark at the edge of the European continent, close to the ocean and with prevailing westerly winds; all factors that contribute to an average of 121 rain days each year. Arising from these rainy weather conditions comes the attitude that a quick rain shower may be beautiful, as well as moody- but first and foremost requires the right outfit. Rains focus on the whole experience of going outside on rainy days, issuing an invitation to explore even in the most mercurial weather.</p>', 'published', '[\"logo\\/amazon-echo-studio-high-fidelity-smart-speaker-with-3d-audio-and-alexa-1-glacier.jpg\",\"logo\\/amazon-echo-studio-high-fidelity-smart-speaker-with-3d-audio-and-alexa-1-glacier.jpg\",\"logo\\/amazon-echo-studio-high-fidelity-smart-speaker-with-3d-audio-and-alexa-1-glacier.jpg\",\"logo\\/amazon-echo-studio-high-fidelity-smart-speaker-with-3d-audio-and-alexa-1-glacier.jpg\"]', 'HS-132-A0', 0, 28, 0, 1, 1, 2, 0, 0, 494, NULL, NULL, NULL, 20.00, 10.00, 15.00, 876.00, 1, 73532, '2023-05-02 21:00:37', '2023-05-29 11:08:33', 'in_stock', 0, 'Botble\\ACL\\Models\\User', 'logo/amazon-echo-studio-high-fidelity-smart-speaker-with-3d-audio-and-alexa-1-glacier.jpg', 'digital', NULL, NULL),
