(1868, 0, 'en', 'packages/optimize/optimize', 'collapse_white_space_description', 'This filter reduces bytes transmitted in an HTML file by removing unnecessary whitespace.', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1869, 0, 'en', 'packages/optimize/optimize', 'elide_attributes', 'Elide attributes', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1870, 0, 'en', 'packages/optimize/optimize', 'elide_attributes_description', 'This filter reduces the transfer size of HTML files by removing attributes from tags when the specified value is equal to the default value for that attribute. This can save a modest number of bytes, and may make the document more compressible by canonicalizing the affected tags.', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1871, 0, 'en', 'packages/optimize/optimize', 'inline_css', 'Inline CSS', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1872, 0, 'en', 'packages/optimize/optimize', 'inline_css_description', 'This filter transforms the inline \"style\" attribute of tags into classes by moving the CSS to the header.', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1873, 0, 'en', 'packages/optimize/optimize', 'insert_dns_prefetch', 'Insert DNS prefetch', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1874, 0, 'en', 'packages/optimize/optimize', 'insert_dns_prefetch_description', 'This filter injects tags in the HEAD to enable the browser to do DNS prefetching.', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1875, 0, 'en', 'packages/optimize/optimize', 'remove_comments', 'Remove comments', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1876, 0, 'en', 'packages/optimize/optimize', 'remove_comments_description', 'This filter eliminates HTML, JS and CSS comments. The filter reduces the transfer size of HTML files by removing the comments. Depending on the HTML file, this filter can significantly reduce the number of bytes transmitted on the network.', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1877, 0, 'en', 'packages/optimize/optimize', 'remove_quotes', 'Remove quotes', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1878, 0, 'en', 'packages/optimize/optimize', 'remove_quotes_description', 'This filter eliminates unnecessary quotation marks from HTML attributes. While required by the various HTML specifications, browsers permit their omission when the value of an attribute is composed of a certain subset of characters (alphanumerics and some punctuation characters).', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1879, 0, 'en', 'packages/optimize/optimize', 'defer_javascript', 'Defer javascript', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
(1880, 0, 'en', 'packages/optimize/optimize', 'defer_javascript_description', 'Defers the execution of javascript in the HTML. If necessary cancel deferring in some script, use data-pagespeed-no-defer as script attribute to cancel deferring.', '2023-05-02 21:00:52', '2023-05-25 20:52:38'),
